19	import com.example.starter.json.JsonSupport;
20	import com.example.starter.repo.CustomsRepository;
21	import com.example.starter.repo.IdempotencyRepository;
22	import com.example.starter.repo.ReviewRepository;
23	import org.springframework.dao.DataAccessException;
24	import org.springframework.stereotype.Service;
25	import org.springframework.transaction.support.TransactionTemplate;
26	
27	import java.time.Instant;
28	import java.util.List;
29	import java.util.Map;
30	
31	/**
32	 * 进口通关单核销衔接服务：通关登记、子批绑定预占、撤销、余量修订、签发前撤回与台账查询。
33	 *
34	 * <p>并发统一由行锁按固定顺序 customs_declaration → subbatch_binding 序列化；
35	 * 新写操作以 requestId 幂等，业务、版本与幂等结果同事务，业务失败回滚不占键。
36	 * 国内批次不经本服务，保留原批签发门禁不变。
37	 */
38	@Service
39	public class CustomsService {
40	
41	    private final CustomsRepository customsRepository;
42	    private final ReviewRepository reviewRepository;
43	    private final IdempotencyRepository idempotencyRepository;
44	    private final JsonSupport jsonSupport;
45	    private final TransactionTemplate txTemplate;
46	
47	    public CustomsService(CustomsRepository customsRepository,
48	                          ReviewRepository reviewRepository,
49	                          IdempotencyRepository idempotencyRepository,
50	                          JsonSupport jsonSupport,
51	                          TransactionTemplate txTemplate) {
52	        this.customsRepository = customsRepository;
53	        this.reviewRepository = reviewRepository;
54	        this.idempotencyRepository = idempotencyRepository;
55	        this.jsonSupport = jsonSupport;
56	        this.txTemplate = txTemplate;
57	    }
58	
59	    // ============================ 通关登记 ============================
60	
61	    /** 登记合成通关单（requestId 幂等）。数量必须为正，版本从 1 开始；同号重复登记 409。 */
62	    public ServiceResult register(CustomsRegisterRequest request) {
63	        return idempotent(request.requestId(), Fingerprints.CUSTOMS_REGISTER,
64	                Fingerprints.customsRegister(request), () -> doRegister(request));
65	    }
66	
67	    private ServiceResult doRegister(CustomsRegisterRequest request) {
68	        Instant now = request.at();
69	        CustomsDeclaration declaration = new CustomsDeclaration();
70	        declaration.setCustomsNo(request.customsNo().trim());
71	        declaration.setEnterpriseName(request.enterpriseName().trim());
72	        declaration.setProductName(request.productName().trim());
73	        declaration.setValidUntil(request.validUntil());
74	        declaration.setTotalQuantity(request.totalQuantity());
75	        declaration.setReservedQuantity(0);
76	        declaration.setWrittenOffQuantity(0);
77	        declaration.setStatus(CustomsStatus.ACTIVE);
78	        declaration.setVersion(1);
79	        declaration.setCreatedAt(now);
80	        declaration.setUpdatedAt(now);
81	
82	        Long id = customsRepository.insert(declaration);
83	        if (id == null) {
84	            throw new BusinessException(409, "CUSTOMS_NO_TAKEN",
85	                    "通关单号已存在: " + request.customsNo());
86	        }
87	        declaration.setId(id);
88	        return ServiceResult.ok(toLedger(declaration, List.of()));
89	    }
90	
91	    // ============================ 子批绑定（预占） ============================
92	
93	    /**
94	     * 包装子批绑定通关单并预占申报支数（requestId 幂等）。
95	     * 任一资料不符（企业/品种不一致、超余量、重复绑定、单已撤销/失效）整笔拒绝。
96	     */
97	    public ServiceResult bind(CustomsBindRequest request) {
98	        return idempotent(request.requestId(), Fingerprints.CUSTOMS_BIND,
99	                Fingerprints.customsBind(request), () -> doBind(request));
100	    }
101	
102	    private ServiceResult doBind(CustomsBindRequest request) {
103	        Instant now = request.at();
104	        int qty = request.declaredQuantity();
105	
106	        // 固定加锁顺序 customs 在前：先锁并校验通关单，再读取子批（本流程不更新审查行，故无需锁 review）。
107	        CustomsDeclaration customs = customsRepository.lockByCustomsNo(request.customsNo().trim());
108	        if (customs == null) {
109	            throw new BusinessException(404, "CUSTOMS_NOT_FOUND",
110	                    "通关单不存在: " + request.customsNo());
111	        }
112	        Review review = reviewRepository.findByBatchNo(request.batchNo().trim());
113	        if (review == null) {
114	            throw new BusinessException(404, "REVIEW_NOT_FOUND",
115	                    "批号不存在: " + request.batchNo());
116	        }
117	        if (customs.getVersion() != request.expectedVersion()) {
118	            throw new BusinessException(409, "VERSION_CONFLICT",
119	                    "通关单版本已变化，期望 " + request.expectedVersion()
120	                            + "，当前 " + customs.getVersion());
121	        }
122	        if (customs.getStatus() == CustomsStatus.REVOKED) {
123	            throw new BusinessException(422, "CUSTOMS_REVOKED",
124	                    "通关单已撤销，不能再绑定子批: " + customs.getCustomsNo());
125	        }
126	        // 有效截止的时间门禁只在进口签发事务内重查（now<截止，恰截止拒绝），绑定阶段不据此拒绝。
127	        if (!customs.getEnterpriseName().equals(review.getEnterpriseName())) {
128	            throw new BusinessException(422, "BINDING_ENTERPRISE_MISMATCH",
129	                    "子批企业 " + review.getEnterpriseName()
130	                            + " 与通关单登记企业 " + customs.getEnterpriseName() + " 不一致");
131	        }
132	        if (!customs.getProductName().equals(review.getProductName())) {
133	            throw new BusinessException(422, "BINDING_PRODUCT_MISMATCH",
134	                    "子批品种 " + review.getProductName()
135	                            + " 与通关单登记品种 " + customs.getProductName() + " 不一致");
136	        }
137	
138	        int alreadyUsed = customs.getReservedQuantity() + customs.getWrittenOffQuantity();
139	        if (alreadyUsed + qty > customs.getTotalQuantity()) {
140	            throw new BusinessException(422, "INSUFFICIENT_CUSTOMS_QUANTITY",
141	                    "预占支数超过通关单余量：已占/已核 " + alreadyUsed + " + 本次 " + qty
142	                            + " > 总数 " + customs.getTotalQuantity());
143	        }
144	
145	        SubbatchBinding binding = new SubbatchBinding();
146	        binding.setReviewId(review.getId());
147	        binding.setCustomsDeclarationId(customs.getId());
148	        binding.setBatchNo(review.getBatchNo());
149	        binding.setDeclaredQuantity(qty);
150	        binding.setStatus(BindingStatus.RESERVED);
151	        binding.setReservedAt(now);
152	        binding.setCreatedAt(now);
153	        binding.setUpdatedAt(now);
154	        Long bindingId = customsRepository.insertBinding(binding);
155	        if (bindingId == null) {
156	            // 同一子批只能绑定一张通关单（uk_binding_review 落败）。
157	            throw new BusinessException(422, "SUBBATCH_ALREADY_BOUND",
158	                    "该子批已绑定通关单，每个子批只能绑定一张单: " + review.getBatchNo());
159	        }
160	        binding.setId(bindingId);
161	
162	        customs.setReservedQuantity(customs.getReservedQuantity() + qty);
163	        customs.setVersion(customs.getVersion() + 1);
164	        customs.setUpdatedAt(now);
165	        customsRepository.update(customs);
166	
167	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "CUSTOMS_RESERVED",
168	                jsonSupport.write(Map.of(
169	                        "customsNo", customs.getCustomsNo(),
170	                        "declaredQuantity", qty,
171	                        "reservedQuantity", customs.getReservedQuantity(),
172	                        "writtenOffQuantity", customs.getWrittenOffQuantity(),
173	                        "totalQuantity", customs.getTotalQuantity())), now));
174	
175	        return ServiceResult.ok(toLedger(customs, customsRepository.listBindingsByCustomsId(customs.getId())));
176	    }
177	
178	    // ============================ 通关单撤销 ============================
179	
180	    /**
181	     * 撤销通关单（requestId 幂等）：释放全部未签发子批预占并阻断后续签发；
182	     * 已签发（已核销）证据保持不变，逐笔登记风险事件。
183	     */
184	    public ServiceResult revoke(CustomsRevokeRequest request) {
185	        return idempotent(request.requestId(), Fingerprints.CUSTOMS_REVOKE,
186	                Fingerprints.customsRevoke(request), () -> doRevoke(request));
187	    }
188	
189	    private ServiceResult doRevoke(CustomsRevokeRequest request) {
190	        Instant now = request.at();
191	        CustomsDeclaration customs = customsRepository.lockByCustomsNo(request.customsNo().trim());
192	        if (customs == null) {
193	            throw new BusinessException(404, "CUSTOMS_NOT_FOUND",
194	                    "通关单不存在: " + request.customsNo());
195	        }
196	        if (customs.getVersion() != request.expectedVersion()) {
197	            throw new BusinessException(409, "VERSION_CONFLICT",
198	                    "通关单版本已变化，期望 " + request.expectedVersion()
199	                            + "，当前 " + customs.getVersion());
200	        }
201	        if (customs.getStatus() == CustomsStatus.REVOKED) {
202	            // 新 requestId 重复撤销已撤销单：业务拒绝；同 requestId 的重复请求由幂等重放首次结果。
203	            throw new BusinessException(422, "CUSTOMS_ALREADY_REVOKED",
204	                    "通关单已撤销，不能重复撤销: " + customs.getCustomsNo());
205	        }
206	
207	        // 加锁顺序保持 customs → binding：锁定全部未签发（RESERVED）绑定并释放。
208	        List<SubbatchBinding> reserved = customsRepository.lockReservedBindings(customs.getId());
209	        int releasedTotal = 0;
210	        for (SubbatchBinding binding : reserved) {
211	            binding.setStatus(BindingStatus.RELEASED);
212	            binding.setReleasedAt(now);
213	            binding.setVersion(binding.getVersion() + 1);
214	            binding.setUpdatedAt(now);
215	            customsRepository.updateBinding(binding);
216	            releasedTotal += binding.getDeclaredQuantity();
217	            reviewRepository.insertEvent(new ReviewEvent(binding.getReviewId(), "CUSTOMS_RESERVATION_RELEASED",
218	                    jsonSupport.write(Map.of(
219	                            "customsNo", customs.getCustomsNo(),
220	                            "reason", "CUSTOMS_REVOKED",
221	                            "declaredQuantity", binding.getDeclaredQuantity())), now));
222	        }
223	
224	        // 已核销（已签发）子批：证据不变，逐笔记风险事件。
225	        List<SubbatchBinding> all = customsRepository.listBindingsByCustomsId(customs.getId());
226	        for (SubbatchBinding binding : all) {
227	            if (binding.getStatus() == BindingStatus.WRITTEN_OFF) {
228	                reviewRepository.insertEvent(new ReviewEvent(binding.getReviewId(),
229	                        "CUSTOMS_REVOKED_AFTER_ISSUE",
230	                        jsonSupport.write(Map.of(
231	                                "customsNo", customs.getCustomsNo(),
232	                                "risk", "通关单撤销时该子批已签发，核销证据保持不变",
233	                                "writtenOffQuantity", binding.getDeclaredQuantity())), now));
234	            }
235	        }
236	
237	        customs.setReservedQuantity(customs.getReservedQuantity() - releasedTotal);
238	        customs.setStatus(CustomsStatus.REVOKED);
239	        customs.setRevokedAt(now);
240	        customs.setVersion(customs.getVersion() + 1);
241	        customs.setUpdatedAt(now);
242	        customsRepository.update(customs);
243	
244	        return ServiceResult.ok(toLedger(customs, customsRepository.listBindingsByCustomsId(customs.getId())));
245	    }
246	
247	    // ============================ 通关单修订（仅增余量） ============================
248	
249	    /** 修订通关单（requestId 幂等）：仅允许增加总支数，不改历史核销企业品种；撤销单不可修订。 */
250	    public ServiceResult amend(CustomsAmendRequest request) {
251	        return idempotent(request.requestId(), Fingerprints.CUSTOMS_AMEND,
252	                Fingerprints.customsAmend(request), () -> doAmend(request));
253	    }
254	
255	    private ServiceResult doAmend(CustomsAmendRequest request) {
256	        Instant now = request.at();
257	        CustomsDeclaration customs = customsRepository.lockByCustomsNo(request.customsNo().trim());
258	        if (customs == null) {
259	            throw new BusinessException(404, "CUSTOMS_NOT_FOUND",
260	                    "通关单不存在: " + request.customsNo());
261	        }
262	        if (customs.getVersion() != request.expectedVersion()) {
263	            throw new BusinessException(409, "VERSION_CONFLICT",
264	                    "通关单版本已变化，期望 " + request.expectedVersion()
265	                            + "，当前 " + customs.getVersion());
266	        }
267	        if (customs.getStatus() == CustomsStatus.REVOKED) {
268	            throw new BusinessException(422, "CUSTOMS_REVOKED",
269	                    "通关单已撤销，不能修订: " + customs.getCustomsNo());
270	        }
271	        if (request.newTotalQuantity() <= customs.getTotalQuantity()) {
272	            throw new BusinessException(422, "AMEND_MUST_INCREASE",
273	                    "修订只能增加总支数，当前总数 " + customs.getTotalQuantity()
274	                            + "，提交 " + request.newTotalQuantity());
275	        }
276	        customs.setTotalQuantity(request.newTotalQuantity());
277	        customs.setVersion(customs.getVersion() + 1);
278	        customs.setUpdatedAt(now);
279	        customsRepository.update(customs);
280	        return ServiceResult.ok(toLedger(customs, customsRepository.listBindingsByCustomsId(customs.getId())));
281	    }
282	
283	    // ============================ 签发前撤回子批 ============================
284	
285	    /** 签发前撤回子批（requestId 幂等）：释放本子批预占且只释放一次；已核销（已签发）拒绝。 */
286	    public ServiceResult withdraw(SubbatchWithdrawRequest request) {
287	        return idempotent(request.requestId(), Fingerprints.SUBBATCH_WITHDRAW,
288	                Fingerprints.subbatchWithdraw(request), () -> doWithdraw(request));
289	    }
290	
291	    private ServiceResult doWithdraw(SubbatchWithdrawRequest request) {
292	        Instant now = request.at();
293	        Review review = reviewRepository.findByBatchNo(request.batchNo().trim());
294	        if (review == null) {
295	            throw new BusinessException(404, "REVIEW_NOT_FOUND",
296	                    "批号不存在: " + request.batchNo());
297	        }
298	        SubbatchBinding existing = customsRepository.findBindingByReviewId(review.getId());
299	        if (existing == null) {
300	            throw new BusinessException(404, "BINDING_NOT_FOUND",
301	                    "该子批未绑定通关单，无预占可释放: " + review.getBatchNo());
302	        }
303	
304	        // 先锁通关单再锁绑定，保持全局 customs → binding 加锁顺序。
305	        CustomsDeclaration customs = customsRepository.lockById(existing.getCustomsDeclarationId());
306	        SubbatchBinding binding = customsRepository.lockBindingByReviewId(review.getId());
307	        if (binding.getVersion() != request.expectedVersion()) {
308	            throw new BusinessException(409, "VERSION_CONFLICT",
309	                    "子批绑定版本已变化，期望 " + request.expectedVersion()
310	                            + "，当前 " + binding.getVersion());
311	        }
312	        if (binding.getStatus() == BindingStatus.WRITTEN_OFF) {
313	            throw new BusinessException(422, "SUBBATCH_ALREADY_ISSUED",
314	                    "子批已签发核销，不能撤回: " + review.getBatchNo());
315	        }
316	        if (binding.getStatus() == BindingStatus.RELEASED) {
317	            throw new BusinessException(422, "SUBBATCH_ALREADY_RELEASED",
318	                    "子批预占已释放，释放只允许一次: " + review.getBatchNo());
319	        }
320	
321	        binding.setStatus(BindingStatus.RELEASED);
322	        binding.setReleasedAt(now);
323	        binding.setVersion(binding.getVersion() + 1);
324	        binding.setUpdatedAt(now);
325	        customsRepository.updateBinding(binding);
326	
327	        customs.setReservedQuantity(customs.getReservedQuantity() - binding.getDeclaredQuantity());
328	        customs.setVersion(customs.getVersion() + 1);
329	        customs.setUpdatedAt(now);
330	        customsRepository.update(customs);
331	
332	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "SUBBATCH_WITHDRAWN",
333	                jsonSupport.write(Map.of(
334	                        "customsNo", customs.getCustomsNo(),
335	                        "releasedQuantity", binding.getDeclaredQuantity())), now));
336	
337	        return ServiceResult.ok(toLedger(customs, customsRepository.listBindingsByCustomsId(customs.getId())));
338	    }
339	
340	    // ============================ 台账查询 ============================
341	
342	    /** 查询通关单余量台账及全部子批绑定明细；通关单不存在 404。 */
343	    public CustomsLedgerView getLedger(String customsNo) {
344	        CustomsDeclaration customs = customsRepository.findByCustomsNo(customsNo.trim());
345	        if (customs == null) {
346	            throw new BusinessException(404, "CUSTOMS_NOT_FOUND",
347	                    "通关单不存在: " + customsNo);
348	        }
349	        return toLedger(customs, customsRepository.listBindingsByCustomsId(customs.getId()));
350	    }
351	
352	    // ============================ 幂等模板（失败不占键） ============================
353	
354	    /**
355	     * requestId 幂等：同键同参重放首次冻结结果；同键异参 409；
356	     * 业务、版本与幂等结果同事务。业务失败统一抛 {@link BusinessException}（404/409/422），
357	     * 触发整事务回滚，占位记录一并回滚，因此失败不占用 requestId。
358	     * 并发同键落败方在占位插入处撞唯一键，等待首事务定稿后重放首次结果。
359	     */
360	    private ServiceResult idempotent(String requestId, String operation, String fingerprint,
361	                                     TxAction action) {
362	        while (true) {
363	            var existing = idempotencyRepository.find(requestId);
364	            if (existing != null) {
365	                return replayOrConflict(existing, fingerprint);
366	            }
367	            try {
368	                return txTemplate.execute(status -> {
369	                    idempotencyRepository.insertPlaceholder(requestId, operation, fingerprint,
370	                            java.time.Instant.now());
371	                    ServiceResult result = action.run();
372	                    idempotencyRepository.finalize(requestId, result.httpStatus(),
373	                            jsonSupport.write(result.body()));
374	                    return result;
375	                });
376	            } catch (DataAccessException ex) {
377	                // 并发同键：等待首事务定稿；若首事务失败回滚导致记录消失，则本请求自行重试。
378	                var winner = awaitFinalizedOrGone(requestId);
379	                if (winner == null) {
380	                    continue;
381	                }
382	                return replayOrConflict(winner, fingerprint);
383	            }
384	        }
385	    }
386	
387	    @FunctionalInterface
388	    private interface TxAction {
389	        ServiceResult run();
390	    }
391	
392	    private ServiceResult replayOrConflict(com.example.starter.domain.IdempotencyRecord record,
393	                                           String requestFingerprint) {
394	        if (!record.getFingerprint().equals(requestFingerprint)) {
395	            return ServiceResult.status(409, new ErrorResponse("IDEMPOTENCY_FINGERPRINT_MISMATCH",
396	                    "同一 requestId 携带了不同业务参数（含版本或精确时刻），请求被拒绝且业务状态不变"));
397	        }
398	        return ServiceResult.status(record.getHttpStatus(), jsonSupport.readObject(record.getResponseJson()));
399	    }
400	
401	    /**
402	     * 等待并发首事务结果：定稿（http_status 非 0）则返回记录；记录缺失意味着首事务失败回滚、
403	     * 键已释放，返回 null 由调用方自行重试。落败方的重复 INSERT 只会在首事务提交或回滚后才被
404	     * 解除阻塞，因此此处不会观察到“占位中（http_status=0）”的稳态。
405	     */
406	    private com.example.starter.domain.IdempotencyRecord awaitFinalizedOrGone(String requestId) {
407	        for (int i = 0; i < 300; i++) {
408	            var record = idempotencyRepository.find(requestId);
409	            if (record == null) {
410	                return null;
411	            }
412	            if (record.getHttpStatus() != 0) {
413	                return record;
414	            }
415	            try {
416	                Thread.sleep(10);
417	            } catch (InterruptedException ie) {
418	                Thread.currentThread().interrupt();
419	                throw new BusinessException(500, "IDEMPOTENCY_WAIT_INTERRUPTED", "等待首次请求结果时被中断");
420	            }
421	        }
422	        throw new BusinessException(500, "IDEMPOTENCY_RECORD_NOT_FINALIZED",
423	                "并发首请求长时间未定稿: " + requestId);
424	    }
425	
426	    // ============================ 视图装配 ============================
427	
428	    private CustomsLedgerView toLedger(CustomsDeclaration customs, List<SubbatchBinding> bindings) {
429	        int available = customs.getTotalQuantity()
430	                - customs.getReservedQuantity() - customs.getWrittenOffQuantity();
431	        List<BindingView> bindingViews = bindings.stream()
432	                .map(b -> new BindingView(
433	                        b.getBatchNo(),
434	                        b.getDeclaredQuantity(),
435	                        b.getStatus().name(),
436	                        b.getVersion(),
437	                        b.getReservedAt(),
438	                        b.getWrittenOffAt(),
439	                        b.getReleasedAt()))
440	                .toList();
441	        return new CustomsLedgerView(
442	                customs.getCustomsNo(),
443	                customs.getEnterpriseName(),
444	                customs.getProductName(),
445	                customs.getValidUntil(),
446	                customs.getTotalQuantity(),
447	                customs.getReservedQuantity(),
448	                customs.getWrittenOffQuantity(),
449	                available,
450	                customs.getStatus().name(),
451	                customs.getVersion(),
452	                customs.getRevokedAt(),
453	                bindingViews);
454	    }
455	}
