1	package com.example.starter.service;
2	
3	import com.example.starter.AbstractIntegrationTest;
4	import com.example.starter.dto.CustomsBindRequest;
5	import com.example.starter.dto.CustomsLedgerView;
6	import com.example.starter.dto.CustomsRegisterRequest;
7	import com.example.starter.dto.CustomsRevokeRequest;
8	import com.example.starter.dto.IssueRequest;
9	import com.example.starter.dto.ServiceResult;
10	import com.example.starter.time.RaceBusinessClock;
11	import org.junit.jupiter.api.Test;
12	import org.springframework.beans.factory.annotation.Autowired;
13	import org.springframework.boot.test.context.TestConfiguration;
14	import org.springframework.context.annotation.Bean;
15	import org.springframework.context.annotation.Import;
16	import org.springframework.context.annotation.Primary;
17	
18	import java.time.Instant;
19	import java.util.ArrayList;
20	import java.util.List;
21	import java.util.concurrent.CyclicBarrier;
22	import java.util.concurrent.ExecutorService;
23	import java.util.concurrent.Executors;
24	import java.util.concurrent.Future;
25	import java.util.concurrent.TimeUnit;
26	
27	import static org.junit.jupiter.api.Assertions.assertEquals;
28	import static org.junit.jupiter.api.Assertions.assertFalse;
29	import static org.junit.jupiter.api.Assertions.assertTrue;
30	
31	/**
32	 * 进口通关 H2 真实并发测试：
33	 * 1) 余量竞争：多子批并发预占，恰满足容量者成功，其余失败，绝不超占；
34	 * 2) 撤销与签发竞争：按提交顺序唯一，不得既核销又释放，落败方被正确阻断/保留证据。
35	 */
36	@Import(CustomsConcurrencyTest.RaceClockConfig.class)
37	class CustomsConcurrencyTest extends AbstractIntegrationTest {
38	
39	    @TestConfiguration
40	    static class RaceClockConfig {
41	        @Bean
42	        @Primary
43	        RaceBusinessClock raceBusinessClock() {
44	            return new RaceBusinessClock();
45	        }
46	    }
47	
48	    @Autowired
49	    private RaceBusinessClock raceClock;
50	
51	    private static final Instant T0 = Instant.parse("2026-09-01T00:00:00Z");
52	    private static final Instant ISSUE_AT = Instant.parse("2026-09-08T00:00:00Z");
53	    private static final Instant REVOKE_AT = Instant.parse("2026-09-08T01:00:00Z");
54	    private static final Instant VALID_UNTIL = Instant.parse("2026-12-31T00:00:00Z");
55	
56	    @Test
57	    void concurrentBindsNeverExceedTotalAndExactlyCapacityWins() throws Exception {
58	        raceClock.setFallback(T0);
59	        customsService.register(new CustomsRegisterRequest("c-reg", "CI-CONC",
60	                IMPORT_ENTERPRISE, IMPORT_PRODUCT, VALID_UNTIL, 100, T0));
61	
62	        int threads = 10;
63	        int each = 20; // 恰 5 个成功占满 100
64	        for (int i = 0; i < threads; i++) {
65	            prepareIssueableImportBatch("c-d-" + i, "B-CONC-" + i);
66	        }
67	
68	        ExecutorService pool = Executors.newFixedThreadPool(threads);
69	        CyclicBarrier barrier = new CyclicBarrier(threads);
70	        List<Future<Integer>> futures = new ArrayList<>();
71	        for (int i = 0; i < threads; i++) {
72	            final int index = i;
73	            futures.add(pool.submit(() -> {
74	                barrier.await(5, TimeUnit.SECONDS);
75	                // 读-改-写：携带最新 expectedVersion；遇并发版本冲突刷新后重试，
76	                // 最终只在容量不足时收到 422，验证绝不超占而非乐观锁本身。
77	                for (int attempt = 0; attempt < 50; attempt++) {
78	                    int expectedVersion = customsService.getLedger("CI-CONC").version();
79	                    try {
80	                        customsService.bind(new CustomsBindRequest(
81	                                "c-bind-" + index, "CI-CONC", "B-CONC-" + index,
82	                                each, expectedVersion, T0));
83	                        return 200;
84	                    } catch (BusinessException ex) {
85	                        if (ex.getHttpStatus() == 409 && "VERSION_CONFLICT".equals(ex.getError())) {
86	                            continue;
87	                        }
88	                        return ex.getHttpStatus();
89	                    }
90	                }
91	                return 500;
92	            }));
93	        }
94	
95	        List<Integer> statuses = new ArrayList<>();
96	        for (Future<Integer> f : futures) {
97	            statuses.add(f.get(30, TimeUnit.SECONDS));
98	        }
99	        pool.shutdown();
100	
101	        long ok = statuses.stream().filter(s -> s == 200).count();
102	        long rejected = statuses.stream().filter(s -> s == 422).count();
103	        assertEquals(5, ok, "100 支容量、每批 20 支，恰 5 笔成功");
104	        assertEquals(5, rejected, "其余 5 笔必须超占 422");
105	        CustomsLedgerView ledger = customsService.getLedger("CI-CONC");
106	        assertEquals(100, ledger.reservedQuantity(), "并发预占绝不超过总数");
107	        assertEquals(0, ledger.availableQuantity());
108	        assertEquals(5, ledger.bindings().stream().filter(b -> b.status().equals("RESERVED")).count());
109	    }
110	
111	    @Test
112	    void revokeAndIssueRaceHasExactlyOneWinnerAcrossRounds() throws Exception {
113	        for (int round = 0; round < 10; round++) {
114	            final String customsNo = "CI-RACE-" + round;
115	            final String batchNo = "B-RACE-" + round;
116	            final int r = round;
117	
118	            // 申报+评定发生在 T0（公示 09-01→09-08 UTC），再把主时钟推进到 ISSUE_AT 令公示期满生效。
119	            raceClock.setFallback(T0);
120	            customsService.register(new CustomsRegisterRequest("race-reg-" + round, customsNo,
121	                    IMPORT_ENTERPRISE, IMPORT_PRODUCT, VALID_UNTIL, 100, T0));
122	            prepareIssueableImportBatch("race-d-" + round, batchNo);
123	            raceClock.setFallback(ISSUE_AT);
124	            reviewService.settlePublicity(batchNo);
125	            customsService.bind(new CustomsBindRequest("race-bind-" + round, customsNo, batchNo, 30, 1, T0));
126	
127	            ExecutorService pool = Executors.newFixedThreadPool(2);
128	            CyclicBarrier barrier = new CyclicBarrier(2);
129	
130	            Future<Outcome> issueFuture = pool.submit(() -> {
131	                barrier.await(5, TimeUnit.SECONDS);
132	                ServiceResult result = reviewService.issue(batchNo, new IssueRequest("race-issue-" + r));
133	                return result.httpStatus() == 200 ? Outcome.ISSUED : Outcome.BLOCKED;
134	            });
135	            Future<Integer> revokeFuture = pool.submit(() -> {
136	                barrier.await(5, TimeUnit.SECONDS);
137	                try {
138	                    return customsService.revoke(
139	                            new CustomsRevokeRequest("race-revoke-" + r, customsNo, 2, REVOKE_AT)).httpStatus();
140	                } catch (BusinessException ex) {
141	                    // 签发先提交导致版本前进时，撤销以 409 异常落败（写操作失败回滚不占键）。
142	                    return ex.getHttpStatus();
143	                }
144	            });
145	
146	            Outcome issueOutcome = issueFuture.get(30, TimeUnit.SECONDS);
147	            int revokeStatus = revokeFuture.get(30, TimeUnit.SECONDS);
148	            pool.shutdown();
149	
150	            // 两事务在 customs 行锁上序列化，先提交者胜出：
151	            //  - 撤销先提交：签发 422 被阻断，撤销 200；
152	            //  - 签发先提交：撤销凭旧版本号收到 409，刷新版本后重试撤销，仍完成并保留核销+记风险。
153	            if (issueOutcome == Outcome.ISSUED) {
154	                assertEquals(409, revokeStatus, "签发先提交时撤销须以版本冲突落败，不得重复释放/核销");
155	                int currentVersion = customsService.getLedger(customsNo).version();
156	                ServiceResult retryRevoke = customsService.revoke(new CustomsRevokeRequest(
157	                        "race-revoke-retry-" + round, customsNo, currentVersion, REVOKE_AT));
158	                assertEquals(200, retryRevoke.httpStatus(), "刷新版本后撤销仍应完成");
159	
160	                CustomsLedgerView ledger = customsService.getLedger(customsNo);
161	                assertEquals("REVOKED", ledger.status());
162	                assertEquals(30, ledger.writtenOffQuantity(), "签发先成功则核销 30 支保持不变");
163	                assertEquals(0, ledger.reservedQuantity());
164	                assertEquals("WRITTEN_OFF", ledger.bindings().get(0).status());
165	                assertTrue(reviewService.listEvents(batchNo).stream()
166	                                .anyMatch(e -> e.get("eventType").equals("CUSTOMS_REVOKED_AFTER_ISSUE")),
167	                        "撤销晚于签发必须登记风险事件");
168	            } else {
169	                // 撤销先提交：签发被阻断，预占已释放
