15	@Repository
16	public class IdempotencyRepository {
17	
18	    private static final RowMapper<IdempotencyRecord> MAPPER = (rs, rowNum) -> {
19	        IdempotencyRecord record = new IdempotencyRecord();
20	        record.setRequestId(rs.getString("request_id"));
21	        record.setOperation(rs.getString("operation"));
22	        record.setFingerprint(rs.getString("fingerprint"));
23	        record.setHttpStatus(rs.getInt("http_status"));
24	        record.setResponseJson(rs.getString("response_json"));
25	        Timestamp created = rs.getTimestamp("created_at");
26	        record.setCreatedAt(created == null ? null : created.toInstant());
27	        return record;
28	    };
29	
30	    private final JdbcTemplate jdbc;
31	
32	    public IdempotencyRepository(JdbcTemplate jdbc) {
33	        this.jdbc = jdbc;
34	    }
35	
36	    /** 按 requestId 查询首次记录，不存在返回 null。 */
37	    public IdempotencyRecord find(String requestId) {
38	        return jdbc.query("SELECT * FROM idempotency_record WHERE request_id = ?",
39	                MAPPER, requestId).stream().findFirst().orElse(null);
40	    }
41	
42	    /**
43	     * 在业务事务内先插入幂等占位记录（状态码 0、空响应）。
44	     * 与业务变更同事务提交：并发同键事务在此处撞主键，须等待首事务提交后重放。
45	     */
46	    public void insertPlaceholder(String requestId, String operation, String fingerprint, Instant now) {
47	        jdbc.update("""
48	                        INSERT INTO idempotency_record
49	                            (request_id, operation, fingerprint, http_status, response_json, created_at)
50	                        VALUES (?, ?, ?, 0, '', ?)
51	                        """,
52	                requestId, operation, fingerprint, Timestamp.from(now));
53	    }
