/** 将提交读数转换为按片段分组的领域对象；未知片段、缺序号/时刻/温度整笔拒绝。 */
private static Map<Integer, List<com.example.starter.domain.ColdChainReading>> buildReadings(
        ColdChainLedger ledger, List<ColdChainSegment> segments,
        ColdChainReadingsSubmitRequest request, Instant now) {
    Set<Integer> knownSeqs = segments.stream()
            .map(ColdChainSegment::getSegmentSeq).collect(Collectors.toSet());
    List<Integer> unknown = request.segments().stream()
            .map(ColdChainSegmentReadingsInput::segmentSeq)
            .filter(seq -> seq == null || !knownSeqs.contains(seq))
            .toList();
    if (!unknown.isEmpty()) {
        throw new BusinessException(422, "COLD_CHAIN_UNKNOWN_SEGMENT",
                "提交了未登记的片段序号: " + unknown);
    }
    Map<Integer, List<com.example.starter.domain.ColdChainReading>> bySegment =
            new LinkedHashMap<>();
    for (ColdChainSegmentReadingsInput block : request.segments()) {
        if (bySegment.containsKey(block.segmentSeq())) {
            throw new BusinessException(422, "COLD_CHAIN_DUPLICATE_SEGMENT_BLOCK",
                    "片段 " + block.segmentSeq() + " 的读数块重复提交");
        }
        List<com.example.starter.domain.ColdChainReading> readings = new ArrayList<>();
        for (var input : block.readings()) {
            if (input.seq() == null || input.at() == null || input.temperature() == null) {
                // 防御：HTTP 层 @NotNull 已拦截，服务层直调同样不得放行缺序号读数。
                throw new BusinessException(422, "COLD_CHAIN_MISSING_READING_FIELD",
                        "读数缺序号、精确时刻或温度，不得通过（片段 " + block.segmentSeq() + "）");
            }
            com.example.starter.domain.ColdChainReading reading =
                    new com.example.starter.domain.ColdChainReading();
            reading.setLedgerId(ledger.getId());
            reading.setLedgerVersion(ledger.getVersion());
            reading.setSegmentSeq(block.segmentSeq());
            reading.setReadingSeq(input.seq());
            reading.setReadAt(input.at());
            reading.setTemperature(input.temperature());
            reading.setCreatedAt(now);
            readings.add(reading);
        }
        bySegment.put(block.segmentSeq(), readings);
    }
    return bySegment;
}

private static Map<Integer, List<com.example.starter.domain.ColdChainReading>> groupReadings(
        List<com.example.starter.domain.ColdChainReading> readings) {
    return readings.stream().collect(Collectors.groupingBy(
            com.example.starter.domain.ColdChainReading::getSegmentSeq,
            LinkedHashMap::new, Collectors.toList()));
}

/** 已冻结证据比对：片段集合、片内序号、精确时刻与温度逐项一致（温度按数值比较）。 */
private static boolean sameReadings(
        Map<Integer, List<com.example.starter.domain.ColdChainReading>> stored,
        Map<Integer, List<com.example.starter.domain.ColdChainReading>> submitted) {
    if (!stored.keySet().equals(submitted.keySet())) {
        return false;
    }
    for (Map.Entry<Integer, List<com.example.starter.domain.ColdChainReading>> entry
            : stored.entrySet()) {
        List<com.example.starter.domain.ColdChainReading> expected = sorted(entry.getValue());
        List<com.example.starter.domain.ColdChainReading> actual =
                sorted(submitted.get(entry.getKey()));
        if (expected.size() != actual.size()) {
            return false;
        }
        for (int i = 0; i < expected.size(); i++) {
            com.example.starter.domain.ColdChainReading x = expected.get(i);
            com.example.starter.domain.ColdChainReading y = actual.get(i);
            if (x.getReadingSeq() != y.getReadingSeq()
                    || !x.getReadAt().equals(y.getReadAt())
                    || x.getTemperature().compareTo(y.getTemperature()) != 0) {
                return false;
            }
        }
    }
    return true;
}

private static List<com.example.starter.domain.ColdChainReading> sorted(
        List<com.example.starter.domain.ColdChainReading> readings) {
    return readings.stream()
            .sorted(Comparator.comparingInt(com.example.starter.domain.ColdChainReading::getReadingSeq))
            .toList();
}

